            W_B: if (m_axi_bvalid) begin
                m_axi_bready <= 1'b0;
                bresp        <= m_axi_bresp;
                bvalid       <= 1'b1;
                wst          <= W_RESP;
            end
            W_RESP: if (ps_bready && bvalid) begin
                bvalid <= 1'b0;
                bresp  <= OKAY;
                wst    <= W_AW;
