            m_axi_wvalid  <= 1'b0;
            m_axi_bready  <= 1'b0;
            bresp         <= SLVERR;
            bvalid        <= 1'b1;
            wst           <= W_RESP;
        end
        if (slave_rst) begin
            m_axi_awvalid <= 1'b0;
            m_axi_wvalid  <= 1'b0;
            m_axi_bready  <= 1'b0;
