    localparam [2:0] R_AR = 3'd0, R_SLAVE = 3'd1, R_DATA = 3'd2, R_RESP = 3'd3, R_ERR = 3'd4;
    reg [2:0] rst_ = R_AR;
    reg [7:0] r_left = 8'd0;

    always @(posedge clk) begin
        arready <= 1'b0;
        r_wait  <= (rst_ == R_SLAVE || rst_ == R_DATA) ? r_wait + 1'b1 : {TIMEOUT_BITS{1'b0}};
