                rid     <= ps_arid;
                if (ps_arlen != 8'd0 || ps_arsize > 3'd2 || slave_rst) begin
                    r_left <= ps_arlen;
                    rword  <= 32'd0;
                    rresp  <= SLVERR;
                    rlast  <= ps_arlen == 8'd0;
                    rvalid <= 1'b1;
                    rst_   <= R_ERR;
