            R_SLAVE: if (m_axi_arready) begin
                m_axi_arvalid <= 1'b0;
                m_axi_rready  <= 1'b1;
                rst_          <= R_DATA;
            end
            R_DATA: if (m_axi_rvalid) begin
                m_axi_rready <= 1'b0;
                rword        <= m_axi_rdata;
                rresp        <= m_axi_rresp;
                rlast        <= 1'b1;
                rvalid       <= 1'b1;
                rst_         <= R_RESP;
            end
            R_RESP: if (ps_rready && rvalid) begin
                rvalid <= 1'b0;
                rlast  <= 1'b0;
                rresp  <= OKAY;
                rst_   <= R_AR;
            end
            R_ERR: if (ps_rready && rvalid) begin
                if (rlast) begin
                    rvalid <= 1'b0;
                    rlast  <= 1'b0;
                    rresp  <= OKAY;
                    rst_   <= R_AR;
                end else begin
                    r_left <= r_left - 8'd1;
                    rlast  <= r_left == 8'd1;
                end
            end
            default: rst_ <= R_AR;
        endcase
        if ((rst_ == R_SLAVE || rst_ == R_DATA) && (slave_rst || r_expired)) begin
            m_axi_arvalid <= 1'b0;
            m_axi_rready  <= 1'b0;
            rword         <= 32'd0;
            rresp         <= SLVERR;
            rlast         <= 1'b1;
            rvalid        <= 1'b1;
            rst_          <= R_RESP;
        end
