    // Sticky flags, cleared only by the design's reset.
    always @(posedge clk) begin
        if (slave_rst) begin
            bad_access <= 1'b0;
            timed_out  <= 1'b0;
        end else begin
            if ((wst == W_AW && ps_awvalid && !awready && (ps_awlen != 8'd0 || ps_awsize > 3'd2)) ||
