// Byte-pair-encoding tokenizer  [b2]  — module bpe_axil, source included verbatim (SystemVerilog)
// ---- bpe_axil.v ----
// bpe_axil.v -- AXI4-Lite slave wrapper for the byte pair encoding (BPE)
// tokenizer block. The wrapped core (compiled from
// byte_pair_encoding_tokenizer.c) continuously and deterministically
// re-tokenizes a fixed, compile-time input string with a fixed, compile-
// time-learned merge table (see README.md / bpe_vocab.md) -- there is no
// "start" to trigger, it free-runs from reset. A host on this bus selects
// which settled token-buffer slot to inspect (RD_IDX) and reads back the
// tokenizer's output (RD_TOKEN) once the next full pass has settled.
//
//  offset  name      access  bits
//  0x00    RD_IDX    RW      [3:0] which settled token-buffer slot to read
//  0x04    STATUS    RO      [0] DONE -- sticky, set on the core's one-cycle
//                            `done` pulse (a fresh tokenizer pass has just
//                            settled and RD_TOKEN/OUT_LEN now reflect it);
//                            write STATUS with bit 0 set to clear (W1C)
//  0x08    RD_TOKEN  RO      [8:0] buf[RD_IDX] as of the last settled pass
//  0x0C    OUT_LEN   RO      [4:0] settled token count for the last pass
//
// irq_out follows STATUS.DONE.
//
// `done` is a genuine one-cycle pulse (byte_pair_encoding_tokenizer.c pulses
// it manually -- `done = 1; done = 0;` -- across two microcode cycles, not
// via the `one_shot` qualifier, but the effect on an AXI poll is the same
// either way): far too narrow for a slow register poll to catch live, so
// it's edge-detected into a sticky bit here, the same pattern
// blocks/peripherals/spi-master{,-slave} use for their own short pulses.

`timescale 1ns / 1ns

module bpe_axil #(
    parameter integer C_S_AXI_DATA_WIDTH = 32,
    parameter integer C_S_AXI_ADDR_WIDTH = 4
)(
    input  wire                          s_axi_aclk,
    input  wire                          s_axi_aresetn,

    input  wire [C_S_AXI_ADDR_WIDTH-1:0] s_axi_awaddr,
    input  wire                          s_axi_awvalid,
    output reg                           s_axi_awready,

    input  wire [C_S_AXI_DATA_WIDTH-1:0] s_axi_wdata,
    input  wire [3:0]                    s_axi_wstrb,
    input  wire                          s_axi_wvalid,
    output reg                           s_axi_wready,

    output reg                           s_axi_bvalid,
    output wire [1:0]                    s_axi_bresp,
    input  wire                          s_axi_bready,

    input  wire [C_S_AXI_ADDR_WIDTH-1:0] s_axi_araddr,
    input  wire                          s_axi_arvalid,
    output reg                           s_axi_arready,

    output reg  [C_S_AXI_DATA_WIDTH-1:0] s_axi_rdata,
    output wire [1:0]                    s_axi_rresp,
    output reg                           s_axi_rvalid,
    input  wire                          s_axi_rready,

    output wire                          irq_out
);
    wire clk = s_axi_aclk;
    wire rst = ~s_axi_aresetn;
    assign s_axi_bresp = 2'b00;
    assign s_axi_rresp = 2'b00;

    localparam [1:0] A_RD_IDX = 2'd0, A_STATUS = 2'd1,
                     A_RD_TOKEN = 2'd2, A_OUT_LEN = 2'd3;

    // ---- wrapper state ----
    reg [3:0] rd_idx_r   = 4'd0;
    reg       done_r     = 1'b0;   // sticky, edge-detected from the core's pulse
    reg       done_prev  = 1'b0;

    reg [C_S_AXI_ADDR_WIDTH-1:0] aw_addr_r;
    reg                          aw_pend;
    reg [31:0]                   w_data_r;
    reg                          w_pend;

    // ---- wrapped core (compiled from byte_pair_encoding_tokenizer.c) ----
    wire       core_done;
    wire [8:0] core_rd_token;
    wire [4:0] core_out_len;

    byte_pair_encoding_tokenizer u_core (
        .clk(clk), .rst(rst),
        .rd_idx_in(rd_idx_r),
        .rd_token(core_rd_token), .done(core_done), .out_len(core_out_len),
        .len(), .buf_wr_idx(), .buf_wr_val(), .buf2_wr_idx(), .buf2_wr_val(),
        .a_reg(), .b_reg(), .out_reg(), .read_pos(), .next_pos(), .write_pos(),
        .skip_next(), .cur_tok(), .nxt_tok(), .in_range(), .is_match(), .m(),
        .buf__wr_en(), .buf2__wr_en(),
        .debug_adr(), .states_out(), .ready(),
        .lhs_out(), .jmp_flag_out(), .jmp_bus_out(),
        .br_out(), .fj_out(), .next_pc(), .state_capture()
