            if (!done_prev && core_done) done_r <= 1'b1;   // rising-edge latch

            // ---- write address ----
            s_axi_awready <= 1'b0;
            if (!aw_pend && !s_axi_bvalid) s_axi_awready <= 1'b1;
            if (s_axi_awvalid && s_axi_awready) begin
                aw_addr_r <= s_axi_awaddr; aw_pend <= 1'b1;
            end
            // ---- write data ----
            s_axi_wready <= 1'b0;
            if (!w_pend && !s_axi_bvalid) s_axi_wready <= 1'b1;
            if (s_axi_wvalid && s_axi_wready) begin
                w_data_r <= s_axi_wdata; w_pend <= 1'b1;
            end
            // ---- write commit ----
            if (aw_pend && w_pend) begin
                aw_pend <= 1'b0; w_pend <= 1'b0; s_axi_bvalid <= 1'b1;
                case (aw_addr_r[C_S_AXI_ADDR_WIDTH-1:2])
                    A_RD_IDX: rd_idx_r <= w_data_r[3:0];
                    A_STATUS: if (w_data_r[0]) done_r <= 1'b0;   // W1C
                    default: ;
                endcase
            end
            if (s_axi_bvalid && s_axi_bready) s_axi_bvalid <= 1'b0;

            // ---- read ----
            s_axi_arready <= 1'b0;
            if (s_axi_arvalid && !s_axi_rvalid) begin
                s_axi_arready <= 1'b1;
                s_axi_rvalid  <= 1'b1;
                case (s_axi_araddr[C_S_AXI_ADDR_WIDTH-1:2])
                    A_RD_IDX:   s_axi_rdata <= {28'b0, rd_idx_r};
                    A_STATUS:   s_axi_rdata <= {31'b0, done_r};
                    A_RD_TOKEN: s_axi_rdata <= {23'b0, core_rd_token};
                    A_OUT_LEN:  s_axi_rdata <= {27'b0, core_out_len};
                    default:    s_axi_rdata <= 32'b0;
                endcase
            end
            if (s_axi_rvalid && s_axi_rready) s_axi_rvalid <= 1'b0;
        end
    end
