//////////////////////////////////////////////////////////////////////////////////

`timescale 10ns / 1ns

module control #(parameter NUM_TIMERS = 1) (
    input [NUM_TIMERS > 0 ? NUM_TIMERS-1 : 0 : 0] timer_done,
    input [NUM_TIMERS > 0 ? NUM_TIMERS-1 : 0 : 0] timer_sel,
    input varible,
    input var_or_timer,
    input branch,
    input forced_jmp,
    input sub,
    input rtn,
    input clk,
    input rst,
    input interrupt,
    output jmp_enb,
    output reg fired,
    output sub_push,
    output sub_pop
    );

    
    
    genvar i;
    localparam TIM_BITS = (NUM_TIMERS > 0) ? NUM_TIMERS : 1;
    wire [TIM_BITS-1:0] timern_true;
    wire timer_true;
    wire var_true;

    reg interrupt_r;
    generate 

    for (i = 0; i < NUM_TIMERS; i= i+1) begin
      assign timern_true[i] = timer_done[i] & timer_sel[i];
    end
         
    endgenerate
    
    always @(posedge clk) begin
    interrupt_r <= interrupt;
    if (rst==1) begin interrupt_r <= 0; fired <= 0; end
    else if (interrupt == 1 && interrupt_r == 0 ) begin fired <= 1; end
    else fired <= 0;
    end
    
    
    generate
    if (NUM_TIMERS > 0) begin : gen_timer_true
        assign timer_true = (|timern_true) & var_or_timer;
    end else begin : no_timer_true
        assign timer_true = 1'b0;
    end
    endgenerate
   assign var_true = varible & ~var_or_timer;
   assign jmp_enb = (((~var_true & ~timer_true)|sub) & branch) | forced_jmp;
   assign sub_push = (sub&branch) | fired;
   assign sub_pop = rtn;
    
    
endmodule
// ---- next_address.sv ----
//////////////////////////////////////////////////////////////////////////////////
// Company: HotWright Inc.
// Copyright (c) 2022 
// All Rights Reserved
// Engineer: Steve Casselman 
// 
// Create Date: 07/20/2020 08:03:43 PM
// Design Name: hotstate
// Module Name: next_address
// Revision:
// Revision 0.01 - File Created
// Additional Comments:
// 
//////////////////////////////////////////////////////////////////////////////////
`timescale 10ns / 1ns

module next_address#(parameter BUS_WIDTH = 8)(
    input [BUS_WIDTH-1:0] address,
    input [BUS_WIDTH-1:0] jmp_adr,
    input [BUS_WIDTH-1:0] returnadr,
    input [BUS_WIDTH-1:0] interrupt_address,
    input [BUS_WIDTH-1:0] switch_adr,
    input switch_active, 
    input ready,
    input jmp_enb,
    input fired,
    input rst,
    input hlt,
    input sub_pop,
    input interrupt,
    input clk,
    output reg [BUS_WIDTH-1:0] nextadr
    );
    
  
    always @(posedge clk) begin
        if (rst == 1||ready == 0) begin 
        nextadr <= 0;
        end
        else if (hlt == 1) nextadr <= address;
        else
          nextadr <=  switch_active?switch_adr:(fired?interrupt_address:(jmp_enb ? jmp_adr: (sub_pop ? returnadr : address + 1)));
    end
endmodule
