`timescale 10ns / 1ns


/* verilator lint_off WIDTHTRUNC */
module stack #(parameter DEPTH = 4,
               parameter WIDTH = 8
    )  (
    input  [WIDTH-1:0] push_adr,
    output reg [WIDTH-1:0] pop_adr,
    input clk,
    input rst,
    input sub_push,
    input sub_pop,
    input hlt,
    input fired
    );
    
    reg [WIDTH-1:0] stack_ram [DEPTH-1:0];
    reg [DEPTH-1:0] pointer;
    genvar i;
    always @(posedge clk) begin
    if (rst == 1) begin
        pointer <= 0;
        stack_ram[0] <= 0;
        pop_adr <= 0;
    end
    else begin
       if (sub_push == 1 && !hlt) begin
           stack_ram[pointer] <= fired ? push_adr : push_adr + 1;
          pointer <= pointer + 1;
          end
       else if (sub_pop == 1 && pointer > 0) pointer <= pointer - 1;
    end
    if (pointer > 0) pop_adr <= stack_ram[pointer - 1]; 
    end
endmodule
// ---- data_stack.sv ----
// data_stack.sv — Hardware data stack for hotstate function parameter passing.
// Part of the hotstate IP suite (Direction A: --hw-stack).
//
// A synchronous LIFO stack with registered TOS output.  Mirrors stack.sv (return-address
// stack) but carries data words instead of addresses.
//
// Timing: push_data written in cycle N is visible on top_data in cycle N+1.
// This matches how callee pops parameters in the cycles after the sub instruction.
//
// Overflow (push to full) and underflow (pop from empty) are silently ignored.
// The compiler statically bounds call depth (same as check_call_depth()), so
// these conditions should not occur in correct programs.
//
// When push_en and pop_en are both asserted simultaneously, pop wins:
// the pointer decrements and top_data updates; the push is ignored.

`timescale 10ns / 1ns

module data_stack #(
    parameter DEPTH = 32,
    parameter WIDTH = 8
)(
    input  [WIDTH-1:0] push_data,
    input              push_en,
    input              pop_en,
    input              hlt,
    input              clk,
    input              rst,
    output reg [WIDTH-1:0] top_data,
    output             empty,
    output             full
);
    reg [WIDTH-1:0] stack_ram [DEPTH-1:0];
    reg [$clog2(DEPTH):0] pointer;  // extra bit for full detection

    assign empty = (pointer == 0);
    assign full  = (pointer == DEPTH);

    always @(posedge clk) begin
        if (rst) begin
            pointer  <= 0;
            top_data <= 0;
        end else if (!hlt) begin
            // pop wins when both asserted simultaneously
            if (pop_en && !empty) begin
                pointer <= pointer - 1;
            end else if (push_en && !full) begin
                stack_ram[pointer] <= push_data;
                pointer <= pointer + 1;
            end

            // Update registered TOS.
            // pointer holds PRE-operation value here (registered assignments evaluate
            // RHS before the LHS update takes effect this clock edge).
            // After pop: new TOS = stack_ram[pointer-2] (the element below old TOS).
            //   pointer=3 → new pointer=2 → new TOS = stack_ram[1] = stack_ram[pointer-2].
            // After push: new TOS = push_data.
            if (pop_en && pointer > 1)
                top_data <= stack_ram[pointer - 2];
            else if (pop_en && pointer == 1)
                top_data <= 0;          // stack now empty; zero is safe sentinel
            else if (push_en && !full)
                top_data <= push_data;
        end
    end
endmodule
