// Create Date: 09/13/2021 03:27:34 PM
// Design Name: 
// Module Name: switch
// Project Name: 
// Target Devices: 
// Tool Versions: 
// Description: finds the offset into the a table. 
// The table has the addresses of the case statements code. 
// jadr adds an offset into the table to handel mutiple switches
// Dependencies: 
// 
// Revision:
// Revision 0.01 - File Created
// Additional Comments:
// 
//////////////////////////////////////////////////////////////////////////////////
`timescale 10ns / 1ns


module switch #(parameter ADR_BUS_WIDTH = 8,
                parameter SWITCH_MEM_BITS = 8,
                parameter SWITCH_MEM_WORDS = 256,
                parameter FILENAME = "",
                parameter STANDALONE = 0,
                parameter DUAL_BANK = 0     // STANDALONE=0 only: 1 = ping-pong hot-swap, 0 = cheap single-bank streamed-once
                )(
    input [ADR_BUS_WIDTH - 1:0] switch_tdata,
    input switch_tvalid,
    input load_init,       // pulse before streaming a new switch table
    input switch_trigger,  // shared bank-flip trigger (STANDALONE=0 only)
    input [ADR_BUS_WIDTH - 1:0] jmp_adr,
    input [SWITCH_MEM_BITS - 1:0] switch_offset_adr,
    input switch_active,
    input clk,
    input rst,
    output ready,
    output [ADR_BUS_WIDTH - 1:0] switch_adr
    );


    wire [$clog2(SWITCH_MEM_WORDS)-1:0] memadr;

    generate
    if (STANDALONE == 1) begin : gen_standalone
    reg [ADR_BUS_WIDTH-1:0] switch_mem [SWITCH_MEM_WORDS - 1:0];
    // Guarded: yosys elaborates this module's default parameterization
    // (FILENAME="") at least once while building the design hierarchy, even
    // under a generate-if whose condition (STANDALONE==1) only holds for the
    // real, correctly-parameterized instance -- an unguarded $readmemh("")
    // hard-errors synthesis before the real instance is ever reached. An
    // empty FILENAME legitimately means "don't preload" (matches every
    // other loader in this file, and mem.v's SYNTHESIS-guarded zero-fill
    // elsewhere in the tree), not a fatal error.
    initial if (FILENAME != "") $readmemh(FILENAME,switch_mem, 0,SWITCH_MEM_WORDS -1);
    assign switch_adr = switch_active?switch_mem[memadr]:0;
    assign ready = 1'b1;

    end else begin : gen_not_standalone
      if (DUAL_BANK == 1) begin : gen_dual_bank
    // ── Dual-bank ping-pong for runtime loading with hot-swap ──────────
    // Only built when DUAL_BANK=1 (--profile active). Mirrors IP/
    // microcode.sv's dual-bank design exactly, INCLUDING its ever_swapped
    // first-boot bypass -- unlike IP/variable.sv (which has a ROM-seeded
    // bank A and must NOT auto-flip), switch.sv's STANDALONE=0 path has
    // never had a ROM seed of any kind (confirmed: the prior single-bank
    // version above had no $readmemh at all for STANDALONE=0). So both
    // banks genuinely start empty here, exactly like microcode.sv, and the
    // same ever_swapped bypass is needed to avoid a first-boot chicken-
    // and-egg deadlock.
    reg [ADR_BUS_WIDTH-1:0] switch_mem_a [SWITCH_MEM_WORDS - 1:0];  // bank 0
    reg [ADR_BUS_WIDTH-1:0] switch_mem_b [SWITCH_MEM_WORDS - 1:0];  // bank 1

    // Initialised at declaration, the way IP/microcode.sv's dual-bank block
    // does. On an FPGA these come up zero from the bitstream; in simulation
    // they were x, and since `ready`, the bank write target and the active
    // read are all muxed on bank_sel, the tier propagated x from cycle 0.
    // Both banks genuinely start empty here (this module has never had a ROM
    // seed for STANDALONE=0), which is what the load_done_a/b = 0 and the
    // ever_swapped = 0 first-boot bypass below are for.
    reg bank_sel = 1'b0;     // 0 = active A / load B; 1 = active B / load A
    reg [$clog2(SWITCH_MEM_WORDS)-1:0] address_wr = 0;
    reg pending_switch = 1'b0;
    reg load_done_a = 1'b0, load_done_b = 1'b0;
    reg ever_swapped = 1'b0;

    wire effective_trigger = switch_trigger | ~ever_swapped;

    wire [ADR_BUS_WIDTH-1:0] active_switch_mem_out =
        bank_sel ? switch_mem_b[memadr] : switch_mem_a[memadr];
    assign switch_adr = switch_active ? active_switch_mem_out : 0;

     always @ (posedge clk) begin
        // load_init: prepare the inactive bank for a new table stream.
        if (load_init) begin
            address_wr     <= 0;
            pending_switch <= 1'b0;
            if (~bank_sel) load_done_b <= 1'b0;
            else           load_done_a <= 1'b0;

        end else if (switch_tvalid && !pending_switch) begin
            // Write incoming entry to the inactive bank
            if (~bank_sel) switch_mem_b[address_wr] <= switch_tdata;
            else           switch_mem_a[address_wr] <= switch_tdata;

            if (address_wr < (SWITCH_MEM_WORDS - 1)) begin
                address_wr <= address_wr + 1;
            end else begin
                // write that fills the last entry
                pending_switch <= 1'b1;
                if (~bank_sel) load_done_b <= 1'b1;
                else           load_done_a <= 1'b1;
            end
        end

        // Bank flip: swap active/inactive when switch_trigger fires
        // (or immediately on first boot via ever_swapped=0).
        if (pending_switch && effective_trigger) begin
            bank_sel       <= ~bank_sel;
            pending_switch <= 1'b0;
            ever_swapped   <= 1'b1;
        end
     end

    // ready: the currently-active bank holds a complete table.
    assign ready = bank_sel ? load_done_b : load_done_a;
      end else begin : gen_single_bank
    // ── Cheap default tier (DUAL_BANK=0): single bank, streamed once ───
    // No second bank, no bank_sel/pending_switch/ever_swapped -- just a
    // write pointer and a load_done latch. switch.sv has never had a ROM
    // fallback for STANDALONE=0, so streaming is still required to get any
    // content at all, but a live bank-flip is not: no existing example
    // (runtime_load_switch_demo included) ever re-streams a second,
    // different table while the machine is running -- they all load once
    // during reset, then run. switch_trigger is accepted on the port list
    // for interface uniformity with gen_dual_bank but is unused here.
    reg [ADR_BUS_WIDTH-1:0] switch_mem [SWITCH_MEM_WORDS - 1:0];
    // Same reasoning as the dual-bank block above: load_init would clear
    // both of these before any real stream, but until it arrives `ready`
    // is read by the rest of the engine, and x there is not a useful answer.
    reg [$clog2(SWITCH_MEM_WORDS)-1:0] address_wr = 0;
    reg load_done = 1'b0;

    assign switch_adr = switch_active ? switch_mem[memadr] : 0;
    assign ready = load_done;

    always @ (posedge clk) begin
        if (load_init) begin
            address_wr <= 0;
            load_done  <= 1'b0;
        end else if (switch_tvalid && !load_done) begin
            switch_mem[address_wr] <= switch_tdata;
            if (address_wr < (SWITCH_MEM_WORDS - 1)) begin
                address_wr <= address_wr + 1;
            end else begin
                load_done <= 1'b1;
            end
        end
    end
      end
    end
    endgenerate

   assign memadr = {jmp_adr,switch_offset_adr};

endmodule
// ---- timer.sv ----
//////////////////////////////////////////////////////////////////////////////////
// Company: HotWright Inc.
// Engineer: Steve Casseslman
// Copyright (c) 2022
// All Rights Reserved 
// Create Date: 05/27/2021 04:07:58 PM
// Design Name: 
// Module Name: timer
// Project Name: 
// Target Devices: 
// Tool Versions: 
// Description: 
// 
// Dependencies: 
// 
// Revision:
// Revision 0.01 - File Created
// Additional Comments:
// 
//////////////////////////////////////////////////////////////////////////////////
 
`timescale 10ns / 1ns
 
module timer #(parameter NUM_TIMERS = 1,
               parameter TIMER_WIDTH = 8,
               parameter TIM_MEM_WORDS = 1,
               parameter TIM_MEM_ADR_WIDTH = 1,
               parameter TIM_EX_WORDS = 1,
               parameter FILENAME = "",
               parameter STANDALONE = 0,
               parameter DUAL_BANK = 0     // STANDALONE=0 only: 1 = ping-pong hot-swap, 0 = cheap static ROM (default)
               )(
    input [TIMER_WIDTH-1:0] timer_data,
    input [TIM_EX_WORDS-1:0][TIMER_WIDTH-1:0] timer_ex_data,
    input [TIM_MEM_ADR_WIDTH-1:0] timer_mem_adr,
    input [NUM_TIMERS-1:0] timer_ld,
    input [NUM_TIMERS-1:0] timer_sel,
    input external,
    input tim_tvalid,
    input load_init,       // pulse before streaming a new timer-limit table (shared with sm/vd/switch's load_init)
    input switch_trigger,  // shared bank-flip trigger (STANDALONE=0, DUAL_BANK=1 only)
    input clk,
    input rst,
    output ready,
    output [NUM_TIMERS-1:0] timer_done,
    output [NUM_TIMERS-1:0][TIMER_WIDTH-1:0] count_out   // current count values (always present)
    );

    reg [TIMER_WIDTH-1:0] count [NUM_TIMERS-1:0];
    // Combinational read of the currently-active timer-limit storage,
    // indexed by timer_mem_adr; driven differently per STANDALONE/DUAL_BANK
    // tier below. Declared outside any generate block since it's consumed
    // by the per-timer for-loop further down, which also lives outside.
    wire [TIMER_WIDTH-1:0] timer_mem_out;
    // Pulses for one cycle when the active timer-limit bank flips
    // (DUAL_BANK=1 only) -- see the swap-time count-reset design note below.
    wire count_reset;

    generate
    if (STANDALONE == 1) begin : gen_standalone
        reg [TIMER_WIDTH-1:0] timer_mem [TIM_MEM_WORDS -1:0];
        initial begin
            if (FILENAME != "") $readmemh(FILENAME, timer_mem, 0, TIM_MEM_WORDS -1);
        end
        assign timer_mem_out = timer_mem[timer_mem_adr];
        assign ready = 1'b1;
        assign count_reset = 1'b0;
    end else begin : gen_not_standalone
      if (DUAL_BANK == 1) begin : gen_dual_bank
        // ── Dual-bank ping-pong for runtime loading with hot-swap ────────
        // Only built when DUAL_BANK=1 (--profile active). Mirrors IP/
        // variable.sv's pattern (not switch.sv's): timer_mem, like vardata,
        // already had a $readmemh ROM seed even before dual-bank existed
        // (limits were historically assumed fixed across swapped
        // algorithms), so bank A is valid from cycle 0 and no ever_swapped
        // first-boot bypass is needed or wanted -- every bank flip,
        // including the first one that ever streams real data, requires an
        // explicit switch_trigger pulse, same reasoning as Section 1.
        reg [TIMER_WIDTH-1:0] timer_mem_a [TIM_MEM_WORDS -1:0];  // bank 0
        reg [TIMER_WIDTH-1:0] timer_mem_b [TIM_MEM_WORDS -1:0];  // bank 1

        initial begin
            if (FILENAME != "") $readmemh(FILENAME, timer_mem_a, 0, TIM_MEM_WORDS -1);
        end

        // Initialised at declaration, the way IP/microcode.sv's dual-bank
        // block does. On an FPGA these come up zero from the bitstream, so
        // hardware was fine; in simulation they were x, and `ready` and the
        // limit read are both muxed on bank_sel, so the whole runtime-load
        // tier propagated x from cycle 0 -- which is why nothing had noticed:
        // every example that simulates a timer builds STANDALONE=1, where
        // this block is not generated at all.
        reg bank_sel = 1'b0;                // 0 = active A / load B; 1 = active B / load A
        reg [TIM_MEM_ADR_WIDTH-1:0] address_wr = 0; // write pointer into the inactive bank
        reg pending_switch = 1'b0;
        reg load_done_a = 1'b1;             // bank A is ROM-seeded and valid from cycle 0
        reg load_done_b = 1'b0;             // bank B is genuinely empty until streamed

        assign timer_mem_out = bank_sel ? timer_mem_b[timer_mem_adr] : timer_mem_a[timer_mem_adr];
        assign ready = bank_sel ? load_done_b : load_done_a;
        // Design decision (Section 9, option a): reset all count[i] on the
        // same pulse that flips the bank, so a swap never leaves a stale
        // count around from the previous program's limits. Cheap: this
        // pulse is already computed for the bank-flip itself.
        assign count_reset = pending_switch && switch_trigger;

        always @(posedge clk) begin
            if (load_init) begin
                address_wr     <= 0;
                pending_switch <= 1'b0;
                if (~bank_sel) load_done_b <= 1'b0;
                else           load_done_a <= 1'b0;

            end else if (tim_tvalid && !pending_switch) begin
                if (~bank_sel) timer_mem_b[address_wr] <= timer_data;
                else           timer_mem_a[address_wr] <= timer_data;

                if (address_wr < (TIM_MEM_WORDS - 1)) begin
                    address_wr <= address_wr + 1;
                end else begin
                    pending_switch <= 1'b1;
                    if (~bank_sel) load_done_b <= 1'b1;
                    else           load_done_a <= 1'b1;
                end
            end

            if (pending_switch && switch_trigger) begin
                bank_sel       <= ~bank_sel;
                pending_switch <= 1'b0;
            end
        end
      end else begin : gen_single_bank
        // ── Cheap default tier (DUAL_BANK=0): single ROM-seeded bank ────
        // No second bank, no streaming write path at all -- tim_tvalid/
        // timer_data/load_init/switch_trigger are accepted on the port
        // list for interface uniformity with gen_dual_bank but are
        // intentionally unused here. This reproduces what every existing
        // --runtime-load example has always actually needed: timer limits
        // fixed across swapped algorithms, loaded once from FILENAME at
        // elaboration.
        reg [TIMER_WIDTH-1:0] timer_mem [TIM_MEM_WORDS -1:0];
        initial begin
            if (FILENAME != "") $readmemh(FILENAME, timer_mem, 0, TIM_MEM_WORDS -1);
        end
        assign timer_mem_out = timer_mem[timer_mem_adr];
        assign ready = 1'b1;
        assign count_reset = 1'b0;
      end
    end
    endgenerate

    generate
    genvar i;

    // here we generate the timers
    for(i=0;i<NUM_TIMERS;i = i + 1)
    begin


    always @(posedge clk) begin
    if(rst == 1 || count_reset)  count[i] <= 0;

    else if (timer_ld[i] == 1 && timer_sel[i] == 1) begin
        /* verilator lint_off WIDTHTRUNC */
        if (external == 1) count[i] <= timer_ex_data[timer_mem_adr];
        else count[i] <= timer_mem_out;
        /* verilator lint_on WIDTHTRUNC */
    end

    else if (timer_sel[i] == 1 && count[i] > 0 ) count[i] <= count[i] - 1;
    end

    assign timer_done[i] = (count[i] == 0 && timer_sel[i] == 1 && timer_ld[i] == 0);
    assign count_out[i]  = count[i];

    end
    endgenerate

endmodule
// ---- variable.sv ----
//////////////////////////////////////////////////////////////////////////////////
// Company: Hotwright Inc.
// Copyright (c) 2022 
// All Rights Reserved
// Engineer: Steve Casselman
//
// Create Date: 06/24/2020
// Module Name: variable
// Description: Unified UberLUT (Truth Table). 
// Each row in the LUT contains results for all possible varSel values 
// for a given state of the variable input bus.
//
//////////////////////////////////////////////////////////////////////////////////

`timescale 10ns / 1ns

module variable #(
               parameter NUM_VARS = 10,           // Width of the input variable bus
               parameter NUM_VARS_ADDR_BITS = NUM_VARS, // Truth-table address width (clamped to <=25 by the
                                                   // compiler's generate_vardata_mem_file() correctness clamp --
                                                   // must match here, since the table array is sized off this,
                                                   // not off NUM_VARS. Defaults to NUM_VARS for any caller that
                                                   // doesn't override it, matching this module's pre-clamp behavior.
               parameter NUM_VARSEL = 1,          // (unused in this implementation)
               parameter NUM_VARSEL_BITS = 4,     // Number of bits for selecting which expression
               parameter FILENAME = "",
               parameter STANDALONE = 0,
               parameter DUAL_BANK = 0            // STANDALONE=0 only: 1 = ping-pong hot-swap, 0 = cheap single ROM bank
               )(
               input clk,
               input rst,
               input [NUM_VARS-1:0] variable,     // Input variable bus (Address)
               input [NUM_VARSEL_BITS-1:0] varSel, // Expression selector (Bit Index)
               input [(1 << NUM_VARSEL_BITS)-1:0] vd_tdata, // Full truth-table row, streamed one row/cycle
               input vd_tvalid,                   // Row-valid strobe for vd_tdata
               input vd_load_init,                // Pulse before streaming a new table; resets write pointer
               input switch_trigger,              // Shared bank-flip trigger (STANDALONE=0 only)
               output ready,
               output lhs
               );

// Truth table: 2^NUM_VARS entries, each (1 << NUM_VARSEL_BITS) wide.
// This layout allows each BRAM row to store all expression results for a given input state.
// STANDALONE=1 only: single ROM bank, preloaded from file, read directly by `lhs` below.
// (STANDALONE=0's dual-bank equivalent, code_a/code_b, is declared inside gen_not_standalone.)
if (STANDALONE == 1) begin : gen_standalone
    reg [ (1 << NUM_VARSEL_BITS)-1 : 0 ] code [ (1 << NUM_VARS_ADDR_BITS)-1 : 0 ];
    initial begin
        $display("DEBUG_VARS: NUM_VARSEL_BITS=%0d NUM_VARS=%0d NUM_VARS_ADDR_BITS=%0d FILENAME=%s", NUM_VARSEL_BITS, NUM_VARS, NUM_VARS_ADDR_BITS, FILENAME);
        if (FILENAME != "") begin
            $readmemh(FILENAME, code);
        end
    end
    // Address with only the low NUM_VARS_ADDR_BITS of `variable` -- correct
    // ONLY while any bits above that stay 0 at runtime (the same correctness
    // caveat generate_vardata_mem_file()'s clamp warning documents).
    assign lhs = code[variable[NUM_VARS_ADDR_BITS-1:0]][varSel];
end

generate
if (STANDALONE == 0) begin : gen_not_standalone
  if (DUAL_BANK == 1) begin : gen_dual_bank
    // ── Dual-bank ping-pong for runtime loading with hot-swap ──────────
    // Only built when DUAL_BANK=1 (--profile active): this is the tier
    // that costs a second full table (measured ~2x LUT4/RAM on switch.sv
    // at comparable sizes) plus bank-flip control logic. Gated off by
    // default because the vast majority of --runtime-load designs only
    // ever hot-swap smdata between sibling programs that share one static
    // vardata table (algo_swap, shader_JIT, systolic_dynamic, tutorials/
    // runtime_swap) -- none of them need a second vardata bank, so they
    // get the cheap gen_single_bank tier below instead.
    //
    // Mirrors IP/microcode.sv's dual-bank design, with one deliberate
    // difference: microcode.sv's banks start empty (nothing is usable
    // until the first full smdata stream completes), so it needs the
    // ever_swapped=0 bypass to auto-flip on first load and break that
    // chicken-and-egg deadlock. Here, bank A is ROM-seeded from FILENAME
    // at elaboration (same as every existing --runtime-load example
    // relies on today — the vardata table has historically been static
    // and shared across swapped programs), so bank A is already valid at
    // cycle 0. An ever_swapped-style bypass would therefore be actively
    // wrong: it would auto-flip on the very first real vardata stream
    // (into bank B) the moment loading completes, without waiting for
    // switch_trigger — racing ahead of the other three dual-bank modules
    // (microcode/switch/timer) and breaking the atomic, trigger-gated
    // flip that Section 11 of the runtime-reloadable-microcode plan
    // relies on. So: every bank flip here, including the first one that
    // ever streams real data, requires an explicit switch_trigger pulse.
    reg [ (1 << NUM_VARSEL_BITS)-1 : 0 ] code_a [ (1 << NUM_VARS_ADDR_BITS)-1 : 0 ];  // bank 0
    reg [ (1 << NUM_VARSEL_BITS)-1 : 0 ] code_b [ (1 << NUM_VARS_ADDR_BITS)-1 : 0 ];  // bank 1

    initial begin
        if (FILENAME != "") begin
            $readmemh(FILENAME, code_a);
        end
    end

    // Initialised at declaration, the way IP/microcode.sv's dual-bank block
    // does. On an FPGA these come up zero from the bitstream, so hardware was
    // fine; in simulation they were x, and both `ready` and the active row are
    // muxed on bank_sel, so the whole tier propagated x from cycle 0. Nothing
    // had noticed because every example that simulates a variable block is
    // either STANDALONE=1 or DUAL_BANK=0, neither of which generates this.
    reg bank_sel = 1'b0;                     // 0 = active A / load B; 1 = active B / load A
    reg [NUM_VARS_ADDR_BITS-1:0] address_wr = 0; // write pointer into the inactive bank
    reg pending_switch = 1'b0;
    // load_done_a starts TRUE: bank A is ROM-seeded and valid from cycle 0,
    // matching this module's historical `ready = 1'b1` behavior for every
    // existing example that never streams vardata at all. load_done_b
    // starts FALSE: bank B is genuinely empty until actually streamed.
    reg load_done_a = 1'b1;
    reg load_done_b = 1'b0;

    wire [ (1 << NUM_VARSEL_BITS)-1 : 0 ] active_row = bank_sel ? code_b[variable[NUM_VARS_ADDR_BITS-1:0]] : code_a[variable[NUM_VARS_ADDR_BITS-1:0]];
    assign lhs = active_row[varSel];

    always @(posedge clk) begin
        // vd_load_init: prepare the inactive bank for a new table stream.
        // Clears the write pointer and the inactive bank's load_done flag.
        if (vd_load_init) begin
            address_wr     <= 0;
            pending_switch <= 1'b0;
            if (~bank_sel) load_done_b <= 1'b0;
            else           load_done_a <= 1'b0;

        end else if (vd_tvalid && !pending_switch) begin
            // Write incoming row to the inactive bank
            if (~bank_sel) code_b[address_wr] <= vd_tdata;
            else           code_a[address_wr] <= vd_tdata;

            if (address_wr < (1 << NUM_VARS_ADDR_BITS) - 1) begin
                address_wr <= address_wr + 1;
            end else begin
                // All rows received; mark the inactive bank done and
                // request a switch at the next switch_trigger pulse.
                pending_switch <= 1'b1;
                if (~bank_sel) load_done_b <= 1'b1;
                else           load_done_a <= 1'b1;
            end
        end

        // Bank flip: swap active/inactive when switch_trigger fires.
        if (pending_switch && switch_trigger) begin
            bank_sel       <= ~bank_sel;
            pending_switch <= 1'b0;
        end
    end

    // ready: the currently-active bank holds a complete/valid table.
    assign ready = bank_sel ? load_done_b : load_done_a;
  end else begin : gen_single_bank
    // ── Cheap default tier (DUAL_BANK=0): single ROM-seeded bank ───────
    // No second bank, no bank_sel/pending_switch/ever_swapped control
    // logic -- vd_tvalid/vd_tdata/vd_load_init/switch_trigger are accepted
    // on the port list for interface uniformity with gen_dual_bank but are
    // intentionally left unused here. This reproduces exactly what every
    // existing --runtime-load example (none of which ever pulse vd_tvalid)
    // has always actually exercised: a table loaded once from FILENAME at
    // elaboration, valid from cycle 0.
    reg [ (1 << NUM_VARSEL_BITS)-1 : 0 ] code [ (1 << NUM_VARS_ADDR_BITS)-1 : 0 ];
    initial begin
        if (FILENAME != "") begin
            $readmemh(FILENAME, code);
        end
    end
    assign lhs   = code[variable[NUM_VARS_ADDR_BITS-1:0]][varSel];
    assign ready = 1'b1;
  end
end else begin : gen_standalone_ready
    // lhs is driven by the gen_standalone block above (STANDALONE==1).
    assign ready = 1'b1;
end
endgenerate

endmodule
